def maxKSumPairs(nums, k):
    a = sorted(nums)
    lo, hi = 0, len(a) - 1
    ops = 0
    while lo < hi:
        s = a[lo] + a[hi]
        if s == k:
            ops += 1
            lo += 1
            hi -= 1
        elif s < k:
            lo += 1
        else:
            hi -= 1
    return ops
